import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast via Steiner-tree search: greedy cheapest-attachment (SPH)
    trees under many orderings (fixed, dynamic best-fit, seeded random
    restarts), non-terminal pruning, and per-dst hybrid rerouting against
    direct shortest paths; the cheapest plan's edge lists are reused across
    all partitions so shared trunk edges are never transferred redundantly."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    dist_cache = {}

    def sp_from(node):
        if node not in dist_cache:
            dist, paths = nx.single_source_dijkstra(h, node, weight="cost")
            dist_cache[node] = (dist, paths)
        return dist_cache[node]

    def plan_total(paths_dict):
        """Broadcast pays each unique edge once: sum costs of the union of
        all per-dst path edges (shared trunk edges are not re-charged)."""
        edges = set()
        for p in paths_dict.values():
            for i in range(len(p) - 1):
                edges.add((p[i], p[i + 1]))
        total = 0.0
        for s, t in edges:
            d = G[s][t] if G.has_edge(s, t) else None
            if d is None or d.get("cost") is None:
                return None
            total += d["cost"]
        return total

    def plan_from_tree(tree):
        """Extract each dst's cheapest path inside the tree using an
        explicit cost-weighted projection (tree edges carry only 'data')."""
        w = nx.DiGraph()
        for s, t in tree.edges():
            d = tree[s][t].get("data") or G.get_edge_data(s, t) or {}
            w.add_edge(s, t, cost=d.get("cost", 1))
        paths_dict = {}
        for dst in dsts:
            try:
                paths_dict[dst] = nx.shortest_path(w, src, dst, weight="cost")
            except Exception:
                return None
        return paths_dict

    def build_tree(order):
        """Greedy Steiner (SPH): attach dsts in the given order, each via
        the cheapest path from any node already in the tree."""
        tree_nodes = {src}
        tree = nx.DiGraph()
        for dst in order:
            best = None  # (cost, path)
            for node in tree_nodes:
                dist, paths = sp_from(node)
                if dst in dist and (best is None or dist[dst] < best[0]):
                    best = (dist[dst], paths[dst])
            if best is None:
                dist, paths = sp_from(src)
                if dst not in dist:
                    continue  # unreachable, skip
                best = (dist[dst], paths[dst])
            path = best[1]
            for i in range(len(path) - 1):
                s, t = path[i], path[i + 1]
                if not tree.has_edge(s, t):
                    tree.add_edge(s, t, data=G[s][t])
                tree_nodes.update([s, t])
        return tree

    def dynamic_tree():
        """SPH with best-fit ordering: repeatedly attach the dst having the
        globally cheapest attachment cost to the current tree."""
        tree_nodes = {src}
        tree = nx.DiGraph()
        remaining = set(dsts)
        while remaining:
            best = None  # (cost, path, dst)
            for node in tree_nodes:
                dist, paths = sp_from(node)
                for dst in remaining:
                    if dst in dist and (best is None or dist[dst] < best[0]):
                        best = (dist[dst], paths[dst], dst)
            if best is None:
                dist, paths = sp_from(src)
                cand = [(dist[d], paths[d], d) for d in remaining if d in dist]
                if not cand:
                    break
                best = min(cand, key=lambda x: x[0])
            _, path, dst = best
            for i in range(len(path) - 1):
                s, t = path[i], path[i + 1]
                if not tree.has_edge(s, t):
                    tree.add_edge(s, t, data=G[s][t])
                tree_nodes.update([s, t])
            remaining.discard(dst)
        return tree

    def prune_tree(tree):
        """Drop non-terminal dead-end nodes that no dst's path needs."""
        terminals = set(dsts) | {src}
        changed = True
        while changed:
            changed = False
            for n in list(tree.nodes()):
                if n not in terminals and tree.out_degree(n) == 0:
                    tree.remove_node(n)
                    changed = True
        return tree

    def hybrid_improve(paths_dict):
        """Local search: reroute a dst onto its direct shortest path whenever
        that lowers the unique-edge union total (freeing edges used only by
        that dst); repeat until no single-dst switch helps."""
        total = plan_total(paths_dict)
        if total is None:
            return paths_dict, None
        _, direct_paths = sp_from(src)
        improved = True
        while improved:
            improved = False
            for dst in dsts:
                if dst not in direct_paths:
                    continue
                cand = dict(paths_dict)
                cand[dst] = direct_paths[dst]
                t2 = plan_total(cand)
                if t2 is not None and t2 < total - 1e-9:
                    paths_dict = cand
                    total = t2
                    improved = True
        return paths_dict, total

    # candidate plans
    direct_dist, direct_paths_all = sp_from(src)
    candidates = []
    direct_plan = {d: direct_paths_all[d] for d in dsts if d in direct_paths_all}
    if len(direct_plan) == len(dsts):
        candidates.append(direct_plan)

    orders = [
        list(dsts),
        sorted(dsts),
        sorted(dsts, reverse=True),
        sorted(dsts, key=lambda d: direct_dist.get(d, float("inf"))),
        sorted(dsts, key=lambda d: -direct_dist.get(d, float("inf"))),
    ]
    from random import Random
    rng = Random(1234)  # deterministic restarts
    for _ in range(15):
        o = list(dsts)
        rng.shuffle(o)
        orders.append(o)

    for order in orders:
        plan = plan_from_tree(prune_tree(build_tree(order)))
        if plan is not None:
            candidates.append(plan)

    plan = plan_from_tree(prune_tree(dynamic_tree()))
    if plan is not None:
        candidates.append(plan)

    best_plan, best_total = None, None
    for plan in candidates:
        t = plan_total(plan)
        if t is not None and (best_total is None or t < best_total):
            best_plan, best_total = plan, t

    # fallback: pure greedy tree, patched with direct paths if needed
    if best_plan is None:
        best_plan = plan_from_tree(build_tree(list(dsts))) or {}
        for dst in dsts:
            if dst not in best_plan and dst in direct_paths_all:
                best_plan[dst] = direct_paths_all[dst]

    # local search on the winner (never increases cost)
    plan2, total2 = hybrid_improve(best_plan)
    if total2 is not None and (best_total is None or total2 < best_total):
        best_plan, best_total = plan2, total2

    # emit: reuse the same edge list for all partitions (no redundant transfers)
    for dst in dsts:
        path = best_plan.get(dst)
        if path is None:
            try:
                path = nx.dijkstra_path(h, src, dst, weight="cost")
            except Exception:
                continue
        edge_list = []
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            data = G[s][t] if G.has_edge(s, t) else {}
            edge_list.append([s, t, data])
        for j in range(bc_topology.num_partitions):
            bc_topology.set_dst_partition_paths(dst, j, list(edge_list))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

